"""Farm, curtain reveal, editable photo reference and collectible purchase in Chromium."""
from pathlib import Path
from playwright.sync_api import sync_playwright
BASE='http://127.0.0.1:8901';ROOT=Path(__file__).resolve().parents[1]
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);p=b.new_page(viewport={'width':390,'height':844});errors=[];p.on('pageerror',lambda e:errors.append(str(e)))
 def control(**kw):return p.request.post(BASE+'/audit/control',data={'mode':'chat',**kw}).json()
 control(work_preview=True,farm_fixture=True);p.goto(BASE+'/work?game=farm');p.wait_for_selector('.fertilizer-card');p.locator('.fertilizer-actions button').first.click();p.wait_for_selector('.fertilizer-use');before=p.request.get(BASE+'/audit/report').json();p.locator('.fertilizer-use').first.click();p.wait_for_function("document.querySelector('#fertilizer-clock').textContent.includes(':')");after=p.request.get(BASE+'/audit/report').json();assert after['work']['farm'][0]['seconds_left']<before['work']['farm'][0]['seconds_left']*.51;assert after['app']['stats']['bucks']==100000;assert after['work']['bucks']==8000
 p.locator('.farm-plot[data-slot="1"]').click();p.wait_for_selector('.farm-splash i',timeout=2500);assert p.locator('.farm-splash i').count()==10;p.screenshot(path='/tmp/remaining-farm.png');p.wait_for_timeout(700)
 p.locator('.farm-test>summary').click();p.get_by_role('button',name='Сбросить тестовое удобрение',exact=True).click();p.wait_for_function("!document.querySelectorAll('.fertilizer-actions button')[1].disabled");p.locator('.fertilizer-actions button').nth(1).click();p.wait_for_selector('.fertilizer-use')
 for width in (320,390,430):
  p.set_viewport_size({'width':width,'height':844});control(avatar_pending=True);p.goto(BASE+'/shop?wardrobe=1');p.wait_for_selector('.curtain-stage.generating');assert p.locator('#wardrobe-generate').is_disabled();assert p.evaluate('document.documentElement.scrollWidth<=innerWidth')
  control(avatar_ready=True);p.wait_for_selector('.curtain-stage.revealed',timeout=6000);p.wait_for_function("document.querySelector('.stage-character').naturalWidth>0");assert '1 фото' in p.locator('#wardrobe-generate').inner_text();p.wait_for_timeout(1900)
  if width==390:p.locator('.curtain-stage').screenshot(path='/tmp/remaining-stage.png')
 control();p.goto(BASE+'/app');p.wait_for_selector('#nav');p.locator('#nav [data-tab="profile"]').click();p.wait_for_selector('.photo-reference-button:not(:disabled)')
 with p.expect_file_chooser() as chooser:p.locator('.photo-reference-button').click()
 chooser.value.set_files(str(ROOT/'assets/fitting_catalog_female___base__.webp'));p.wait_for_selector('#photo-reference-description');p.locator('#photo-reference-description').fill('Короткая стрижка и светлые глаза.');p.locator('#apply-photo-reference').click();p.wait_for_selector('#sheet.on',state='detached');report=p.request.get(BASE+'/audit/report').json();assert report['app']['character']['photo_reference_description']=='Короткая стрижка и светлые глаза.';assert report['app']['stats']['bucks']==100000;assert report['photos']==1;assert not report['avatar']
 control(level=9,inventory={});p.goto(BASE+'/shop?wardrobe=1');p.wait_for_selector('#tabs');p.get_by_role('button',name='🔞 Игрушки 18+',exact=True).click();assert p.locator('#items .card').count()==7;p.wait_for_function("Array.from(document.querySelectorAll('#items .card-img')).every(i=>i.complete&&i.naturalWidth>0)")
 p.locator('#items .buy-btn').first.click();p.wait_for_selector('.collection-favorite');p.locator('.collection-favorite').click();p.wait_for_function("document.querySelector('.collection-favorite').textContent.includes('♥')");report=p.request.get(BASE+'/audit/report').json();assert report['app']['stats']['bucks']==97000;p.screenshot(path='/tmp/remaining-collection.png')
 control(level=8);p.reload();p.wait_for_selector('#tabs');p.get_by_role('button',name='🔞 Игрушки 18+',exact=True).click();assert p.locator('#items .card').count()==0;assert '9' in p.locator('#items').inner_text();assert not errors,errors
 b.close();print('Remaining browser: targeted fertilizer and isolated wallet, test Stars/refill controls, lateral water splash; 320/390/430 curtain pending/reveal; real file selection + editable extraction without photo spend; level-9 collection buy/favorite gates passed')
